32	func TestBuildKubeletArgs(t *testing.T) {
33		tests := []struct {
34			name     string
35			opts     kubeletFlagsOpts
36			expected []kubeadmapi.Arg
37		}{
38			{
39				name: "hostname override",
40				opts: kubeletFlagsOpts{
41					nodeRegOpts: &kubeadmapi.NodeRegistrationOptions{
42						KubeletExtraArgs: []kubeadmapi.Arg{
43							{Name: "hostname-override", Value: "override-name"},
44						},
45					},
46					criSocket: "unix:///var/run/containerd/containerd.sock",
47				},
48				expected: []kubeadmapi.Arg{
49					{Name: "container-runtime-endpoint", Value: "unix:///var/run/containerd/containerd.sock"},
50					{Name: "hostname-override", Value: "override-name"},
51				},
52			},
53			{
54				name: "register with taints",
55				opts: kubeletFlagsOpts{
56					nodeRegOpts: &kubeadmapi.NodeRegistrationOptions{
57						Taints: []v1.Taint{
58							{
59								Key:    "foo",
60								Value:  "bar",
61								Effect: "baz",
62							},
63							{
64								Key:    "key",
65								Value:  "val",
66								Effect: "eff",
67							},
68						},
69					},
70					criSocket:                "unix:///var/run/containerd/containerd.sock",
71					registerTaintsUsingFlags: true,
72				},
73				expected: []kubeadmapi.Arg{
74					{Name: "container-runtime-endpoint", Value: "unix:///var/run/containerd/containerd.sock"},
75					{Name: "register-with-taints", Value: "foo=bar:baz,key=val:eff"},
76				},
77			},
78		}
79	
80		for _, test := range tests {
81			t.Run(test.name, func(t *testing.T) {
82				actual := buildKubeletArgs(test.opts)
83				if !reflect.DeepEqual(actual, test.expected) {
84					t.Errorf(
85						"failed buildKubeletArgs:\n\texpected: %v\n\t  actual: %v",
86						test.expected,
87						actual,
88					)
89				}
90			})
91		}
92	}
