94	func TestGetNodeNameAndHostname(t *testing.T) {
95		hostname, err := os.Hostname()
96		if err != nil {
97			t.Errorf("unexpected error: %v", err)
98		}
99	
100		testCases := []struct {
101			name             string
102			opts             kubeletFlagsOpts
103			expectedNodeName string
104			expectedHostName string
105		}{
106			{
107				name: "overridden hostname",
108				opts: kubeletFlagsOpts{
109					nodeRegOpts: &kubeadmapi.NodeRegistrationOptions{
110						KubeletExtraArgs: []kubeadmapi.Arg{
111							{Name: "hostname-override", Value: "override-name"},
112						},
113					},
114				},
115				expectedNodeName: "override-name",
116				expectedHostName: strings.ToLower(hostname),
117			},
118			{
119				name: "overridden hostname uppercase",
120				opts: kubeletFlagsOpts{
121					nodeRegOpts: &kubeadmapi.NodeRegistrationOptions{
122						KubeletExtraArgs: []kubeadmapi.Arg{
123							{Name: "hostname-override", Value: "OVERRIDE-NAME"},
124						},
125					},
126				},
127				expectedNodeName: "OVERRIDE-NAME",
128				expectedHostName: strings.ToLower(hostname),
129			},
130			{
131				name: "hostname contains only spaces",
132				opts: kubeletFlagsOpts{
133					nodeRegOpts: &kubeadmapi.NodeRegistrationOptions{
134						KubeletExtraArgs: []kubeadmapi.Arg{
135							{Name: "hostname-override", Value: " "},
136						},
137					},
138				},
139				expectedNodeName: " ",
140				expectedHostName: strings.ToLower(hostname),
141			},
142			{
143				name: "empty parameter",
144				opts: kubeletFlagsOpts{
145					nodeRegOpts: &kubeadmapi.NodeRegistrationOptions{
146						KubeletExtraArgs: []kubeadmapi.Arg{
147							{Name: "hostname-override", Value: ""},
148						},
149					},
150				},
151				expectedNodeName: "",
152				expectedHostName: strings.ToLower(hostname),
153			},
154			{
155				name: "nil parameter",
156				opts: kubeletFlagsOpts{
157					nodeRegOpts: &kubeadmapi.NodeRegistrationOptions{
158						KubeletExtraArgs: nil,
159					},
160				},
161				expectedNodeName: strings.ToLower(hostname),
162				expectedHostName: strings.ToLower(hostname),
163			},
164		}
165	
166		for _, tc := range testCases {
167			t.Run(tc.name, func(t *testing.T) {
168				nodeName, hostname, err := GetNodeNameAndHostname(tc.opts.nodeRegOpts)
169				if err != nil {
170					t.Errorf("unexpected error: %v", err)
171				}
172				if nodeName != tc.expectedNodeName {
173					t.Errorf("expected nodeName: %v, got %v", tc.expectedNodeName, nodeName)
174				}
175				if hostname != tc.expectedHostName {
176					t.Errorf("expected hostname: %v, got %v", tc.expectedHostName, hostname)
177				}
178			})
179		}
180	}
