192				expectedValue: []string{"--container-runtime-endpoint=unix:///var/run/containerd/containerd.sock"},
193				expectError:   false,
194			},
195			{
196				name:          "has KUBELET_KUBEADM_ARGS line but no args",
197				fileContent:   `KUBELET_KUBEADM_ARGS=""`,
